function searchRotated(items, target) {
  let lo = 0, hi = items.length - 1, steps = 0;
  while (lo <= hi) {
    steps++;
    const mid = Math.floor((lo + hi) / 2);
    if (items[mid] === target) return [mid, steps];
    if (items[lo] <= items[mid]) {
      if (items[lo] <= target && target < items[mid]) hi = mid - 1;
      else lo = mid + 1;
    } else {
      if (items[mid] < target && target <= items[hi]) lo = mid + 1;
      else hi = mid - 1;
    }
  }
  return [-1, steps];
}
