const unitKobo = 185000;

function totalKobo(quantity) {
  const goods = quantity * unitKobo + 150000;
  return goods + Math.round(goods * 0.075);
}

function largestQuantity(budgetKobo) {
  let lo = 0;
  let hi = Math.floor(budgetKobo / unitKobo) + 2;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (totalKobo(mid) > budgetKobo) hi = mid;
    else lo = mid + 1;
  }
  return lo - 1;
}

const q = largestQuantity(5000000);
