const prices = [800, 1200, 1200, 1200, 4500, 4500, 9000];

function firstTrue(lo, hi, test) {
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (test(mid)) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

function positions(items, price) {
  const first = firstTrue(0, items.length, (i) => items[i] >= price);
  const end = firstTrue(0, items.length, (i) => items[i] > price);
  return first === end ? null : [first, end - 1];
}

console.log(positions(prices, 1200), positions(prices, 4500), positions(prices, 5000));
